package com.meetspace.service; import com.meetspace.dto.BookingDtos.*; import com.meetspace.exception.ApiException; import com.meetspace.repository.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import java.time.*; import java.util.*;
@Service public class BookingService{private final org.springframework.context.ApplicationEventPublisher events;private final UserRepository users;private final BookingRepository bookings;private final EmployeeRepository employees;private final RoomService rooms;public BookingService(BookingRepository b,EmployeeRepository e,RoomService r,UserRepository u,org.springframework.context.ApplicationEventPublisher p){bookings=b;employees=e;rooms=r;users=u;events=p;}private UUID employee(UUID user){return employees.byUser(user).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"EMPLOYEE_NOT_FOUND","Employee profile was not found")).id();}@Transactional(isolation=Isolation.SERIALIZABLE) public Response create(UUID user,Create x){if(x.bookingDate().isBefore(LocalDate.now()))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_BOOKING_DATE","Booking date cannot be in the past");if(!x.startTime().isBefore(x.endTime()))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_TIME_RANGE","Start time must be before end time");employee(user);rooms.get(x.roomId());if(bookings.overlap(x.roomId(),x.bookingDate(),x.startTime(),x.endTime()))throw new ApiException(HttpStatus.CONFLICT,"ROOM_UNAVAILABLE","The selected room is already booked for this time");try{var result=bookings.create(employee(user),x);String recipient=users.findById(user).orElseThrow().email();var room=rooms.get(result.roomId());events.publishEvent(new com.meetspace.realtime.RealtimeEvent(recipient,"BOOKING_CREATED",result.id(),result.roomId(),result.bookingDate(),result.startTime(),result.endTime(),result.status(),java.time.Instant.now()));events.publishEvent(new com.meetspace.notification.EmailNotification(recipient,"MeetSpace booking confirmed","Booking confirmed\nRoom: "+room.name()+" ("+room.roomCode()+")\nDate: "+result.bookingDate()+"\nTime: "+result.startTime()+" - "+result.endTime()+"\nPurpose: "+result.purpose()+"\nStatus: "+result.status()));return result;}catch(DataIntegrityViolationException e){throw new ApiException(HttpStatus.CONFLICT,"ROOM_UNAVAILABLE","The selected room is already booked for this time");}}@Transactional public Response cancel(UUID user,UUID booking){UUID emp=employee(user);var current=bookings.owned(booking,emp).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"BOOKING_NOT_FOUND","Booking was not found"));if(!current.status().equals("PENDING")&&!current.status().equals("CONFIRMED"))throw new ApiException(HttpStatus.CONFLICT,"BOOKING_NOT_CANCELLABLE","This booking cannot be cancelled");if(!bookings.cancel(booking,emp))throw new ApiException(HttpStatus.CONFLICT,"BOOKING_NOT_CANCELLABLE","This booking cannot be cancelled");var result=bookings.owned(booking,emp).orElseThrow();String recipient=users.findById(user).orElseThrow().email();var room=rooms.get(result.roomId());events.publishEvent(new com.meetspace.realtime.RealtimeEvent(recipient,"BOOKING_CANCELLED",result.id(),result.roomId(),result.bookingDate(),result.startTime(),result.endTime(),result.status(),java.time.Instant.now()));events.publishEvent(new com.meetspace.notification.EmailNotification(recipient,"MeetSpace booking cancelled","Booking cancelled\nRoom: "+room.name()+" ("+room.roomCode()+")\nDate: "+result.bookingDate()+"\nTime: "+result.startTime()+" - "+result.endTime()+"\nPurpose: "+result.purpose()+"\nStatus: CANCELLED"));return result;}public List<Response> mine(UUID user){return bookings.byEmployee(employee(user));}public Availability availability(UUID room,LocalDate date,LocalTime start,LocalTime end){if(!start.isBefore(end))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_TIME_RANGE","Start time must be before end time");rooms.get(room);return new Availability(room,date,start,end,!bookings.overlap(room,date,start,end));}}
